'use strict';

// MODULES //

var isDiscreteScaleName = require( '@stdlib/plot/vega/base/assert/is-discrete-scale-name' );
var isObject = require( '@stdlib/assert/is-object' );
var hasProp = require( '@stdlib/assert/has-property' );
var DiscreteScale = require( '@stdlib/plot/vega/scale/discrete' );


// MAIN //

/**
* Tests whether an input value is a discrete scale instance.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is a discrete scale instance
*
* @example
* var DiscreteScale = require( '@stdlib/plot/vega/scale/discrete' );
*
* var v = new DiscreteScale({
*     'name': 'xScale',
*     'type': 'ordinal'
* });
* var bool = isDiscreteScale( v );
* // returns true
*
* bool = isDiscreteScale( {} );
* // returns false
*
* bool = isDiscreteScale( 'foo' );
* // returns false
*/
function isDiscreteScale( value ) {
	return (
		value instanceof DiscreteScale ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			isDiscreteScaleName( value.type ) &&
			hasProp( value, 'name' ) &&
			hasProp( value, 'domain' ) &&
			hasProp( value, 'range' )
		)
	);
}


// EXPORTS //

module.exports = isDiscreteScale;
